/**
 * Bildene skissen trenger, lagt rett inn i koden.
 *
 * De ligger her og ikke som filer i public/, sa hele motoren kan limes inn
 * som tekst. Ingenting ma lastes opp ved siden av.
 *
 *   DISCLAIMER  bunnfeltet fra Informativs utkastmal, uendret
 *   VANNMERKE   Informativ-logoen, med gjennomsiktig bunn
 */
export const DISCLAIMER = "data:image/jpeg;base64,";

export const VANNMERKE = "data:image/png;base64,";

/** Gjor dem om til bilder nettleseren kan tegne. */
export function lastBilder(): Promise<{ disclaimer: any; vannmerke: any }> {
  const en = (url: string) => new Promise<any>((ok, feil) => {
    const i = new Image();
    i.onload = () => ok(i);
    i.onerror = feil;
    i.src = url;
  });
  return Promise.all([en(DISCLAIMER), en(VANNMERKE)])
    .then(([disclaimer, vannmerke]) => ({ disclaimer, vannmerke }));
}
